SETUP_TRANSLATIONS:dict[str,str]={'window':'Configuración inicial','welcome':'Bienvenido','welcome_text':'Este asistente configura el diseño, la escala de pantalla y un primer perfil de refrigeración. Todo se puede cambiar más tarde.','design':'Diseño','appearance':'Apariencia','light':'Claro (predeterminado)','dark':'Oscuro','system':'Modo del sistema','accent':'Color de acento','background':'Fondo animado','display':'Monitor y escala','auto_scale':'Adaptar automáticamente al monitor y a la relación de aspecto','app_scale':'Escala de la aplicación','layout':'Diseño','layout_auto':'Automático','layout_compact':'Compacto · 16:10','layout_standard':'Estándar · 16:9','layout_ultra':'Ultrawide · 21:9','layout_super':'Super ultrawide · 32:9','system_check':'Comprobación del sistema','deps_ok':'Todas las dependencias están instaladas.','deps_missing':'Paquetes que faltan: {packages}. Se pueden instalar más tarde en Ajustes.','detect_after':'Kraken y los controladores RGB se detectarán al finalizar el asistente.','starter':'Perfil inicial','cooling_profile':'Perfil de refrigeración','quiet':'Silencioso · 45% / 35%','balanced':'Equilibrado · 55% / 50%','performance':'Rendimiento · 100% / 100%','safe':'Seguro · 65% / 65%','profile_note':'El perfil se aplica tras detectar correctamente el dispositivo.','finish':'Listo','finish_text':'La aplicación se inicia en modo claro de forma predeterminada. Todas las opciones se pueden cambiar más tarde.','open_help':'Abrir Ayuda y primeros pasos al finalizar','back':'Atrás','next':'Siguiente','finish_button':'Finalizar','cancel':'Cancelar'}
HELP_TOPICS:dict[str,dict[str,object]]={'getting_started':{'title':'Primeros pasos','intro':'Los principales apartados de Open Hardware Control en pocos minutos.','steps':('Elige a la izquierda el dispositivo o apartado del sistema.','Usa perfiles para guardar varias opciones juntas.','Los cambios de hardware solo se transmiten con la acción Aplicar/Iniciar correspondiente.','Abre el registro si algo no responde.'),'page':0},'lcd':{'title':'Cambiar el LCD','intro':'Imágenes, GIF, reloj y datos de hardware se gestionan en el espacio LCD de NZXT.','steps':('Abre Dispositivos → NZXT Kraken → LCD.','Elige contenido estático o animado e importa una imagen o GIF propio si lo deseas.','Los datos de hardware pueden mostrar CPU, GPU y líquido con diseños animados.','Brillo y orientación están en los ajustes de pantalla.','Durante un GIF OHC coordina automáticamente las breves cesiones USB.'),'page':3},'cooling':{'title':'Refrigeración y perfiles','intro':'La bomba y los ventiladores del radiador Kraken pueden usar valores fijos o control por temperatura.','steps':('Abre Dispositivos → NZXT Kraken → Refrigeración.','Usa Silencioso, Equilibrado, Rendimiento o Seguro como punto de partida.','Las curvas pueden usar la temperatura de CPU mientras el líquido sigue como protección.','Vigila temperaturas y RPM antes de usar valores muy bajos.'),'page':1},'rgb':{'title':'RGB Studio','intro':'RGB Studio agrupa dispositivos NZXT y OpenRGB gestionados por OHC.','steps':('Detecta y nombra primero los dispositivos.','Prueba las zonas LED y guarda su cantidad.','Selecciona dispositivos o grupos y después inicia un diseño OHC.','Si otra ventana de OpenRGB controla el hardware, OHC espera una cesión segura.'),'page':2},'profiles':{'title':'Perfiles, importación y copias','intro':'Los perfiles guardan ajustes relacionados de refrigeración, LCD, RGB y diseño.','steps':('Abre Sistema → Perfiles.','Crea perfiles propios y duplícalos antes de cambios grandes.','Los perfiles LCD importados muestran vista previa y elementos no compatibles antes de activarse.','Usa Exportar o Copia de seguridad antes de editar perfiles complejos.'),'page':5},'openlinkhub':{'title':'Corsair y OpenLinkHub','intro':'Los dispositivos Corsair se integran mediante una instancia local de OpenLinkHub.','steps':('Abre Dispositivos → Corsair · OpenLinkHub.','Comprueba contexto del servicio, API y dispositivos detectados.','OHC nunca modifica automáticamente un servicio de sistema ajeno.','Si hay dudas compara los valores con la página del dispositivo en OpenLinkHub.'),'page':8},'settings':{'title':'Ajustes, idioma y autoarranque','intro':'Aquí se configuran apariencia, idioma, pantalla, dependencias y arranque.','steps':('Abre Sistema → Ajustes.','Puedes cambiar entre alemán, inglés, español y francés en cualquier momento.','Al iniciar el escritorio OHC puede permanecer totalmente minimizado en la bandeja.','Los módulos no detectados se pueden mostrar para diagnóstico.'),'page':4},'troubleshooting':{'title':'Solución de problemas y registro','intro':'El registro es la fuente de diagnóstico más útil para problemas de hardware.','steps':('Abre Diagnóstico → Registro y reproduce el fallo una vez.','Usa Copiar todo para adjuntar la sesión a un informe.','Para problemas USB revisa los permisos en Ajustes.','Para RGB actualiza primero la detección de OHC antes de ejecutar otras aplicaciones RGB.'),'page':7},'supported_devices':{'title':'Dispositivos compatibles','intro':'OHC distingue perfiles fijos de los dispositivos que comunican dinámicamente los servicios locales.','steps':('NZXT Kraken: Kraken 2023 (1e71:300e), Kraken Elite 2024 RGB (3012) y Kraken Plus (3014) figuran como compatibles.','Kraken 2023 Elite (300c) solo se detecta de forma segura; la escritura permanece bloqueada por el estado conocido del ''controlador.','NZXT 2023 RGB Controller (2012) se controla mediante liquidctl.','Thermalright Levita Vision 360 ARGB Black: pantalla 1600×720 mediante TRCC Linux; bomba/ventiladores mediante canales hwmon ''confirmados.','Otros dispositivos RGB y Corsair siguen las listas dinámicas de las versiones locales de OpenRGB y OpenLinkHub.','Los ventiladores de placa/caja requieren PWM hwmon compatible y confirmación física; OHC no modifica los ventiladores GPU.'),'page':6},'wallpaper_engine':{'title':'Wallpaper Engine','intro':'Un asistente reutilizable explica Steam, Workshop y el complemento local CaptSilver para Plasma.','steps':('Instala Wallpaper Engine con Steam y suscríbete inicialmente a cinco fondos del Workshop.','En Fedora, OHC puede verificar el SHA256 publicado e instalar el RPM oficial mediante Polkit/DNF tras dos confirmaciones; OHC ''no recibe la contraseña.','Selecciona como biblioteca de Steam la carpeta que contiene steamapps y usa una carpeta pequeña separada para vídeos propios.','Selecciona fondos o vídeos en OHC; las opciones avanzadas siguen en la interfaz original de Plasma.','El estado original es el predeterminado y la optimización opcional se puede revertir.'),'page':9},'desktop':{'title':'Diseños de escritorio','intro':'Los diseños experimentales modifican partes seleccionadas de KDE con copia y restauración.','steps':('Activa el área experimental en Ajustes.','Revisa los cambios antes de aplicarlos.','OHC crea una copia antes de modificar y ofrece restauración.'),'page':10}}
